# %% ../nbs/04_sensitivity.ipynb #40a2aae2
import numpy as np, pandas as pd, torch
from soilspecdl.all import predict
from .pretrain import rt_wns, preprocess
from .instrument_model import InstrumentModel

# %% ../nbs/04_sensitivity.ipynb #24a63924
def perturb(
    X, # Absorbance spectra on `rt_wns`, one per row
    shift_cm=0., # Displacement of every band, in cm⁻¹, positive towards higher wavenumbers
    stretch=0., # Displacement of each band as a fraction of its wavenumber
    sigma_cm=0., # Standard deviation of a Gaussian broadening filter, in cm⁻¹
    gamma=1., # Contrast: absorbance raised to this power
    gain=None, # B-spline coefficients added to a gain of 1, as in `InstrumentModel`
    baseline=None, # B-spline coefficients of an additive baseline, in absorbance
)->np.ndarray: # Perturbed spectra
    "Apply the effects of `InstrumentModel` to `X`, with parameters in physical units"
    wn = rt_wns.astype(float); dw = wn[1] - wn[0]
    on = {'shift': shift_cm or stretch, 'broaden': sigma_cm, 'contrast': gamma != 1, 'gain': gain is not None, 'baseline': baseline is not None}
    m = InstrumentModel(wn, [e for e, v in on.items() if v])
    with torch.no_grad():
        m.shift.copy_(torch.tensor([-(shift_cm + stretch*wn.mean())/dw, -stretch]))
        if sigma_cm: m.log_sigma.fill_(np.log(sigma_cm/dw))
        m.log_gamma.fill_(np.log(gamma))
        if gain is not None: m.g.add_(torch.tensor(gain))
        if baseline is not None: m.b.copy_(torch.tensor(baseline))
        return m(torch.tensor(X, dtype=torch.float64)).numpy()

# %% ../nbs/04_sensitivity.ipynb #f8c3298f
def sensitivity(
    model, # Pretrained model, such as from `load_pretrained`
    X, # Absorbance spectra on `rt_wns`, one per row
    cases, # Dict from a name to a function that turns `X` into perturbed spectra, such as a `partial` of `perturb`
)->pd.DataFrame: # One row per case
    "Mean and RMS of the change in the predictions of `model` when each function in `cases` is applied to `X`"
    f = lambda x: predict(model, preprocess().fit_transform(x), rt_wns).ravel()
    p0 = f(X)
    d = {k: f(fn(X)) - p0 for k, fn in cases.items()}
    return pd.DataFrame({k: {'bias': v.mean(), 'rms': np.sqrt((v**2).mean())} for k, v in d.items()}).T
